{
  "pasos": [
    {
      "id": "s1",
      "op": "search_catalog",
      "args": {
        "query": "freidora de aire",
        "category": "electrodomesticos_cocina",
        "attributes": {"tipo": "freidora de aire"},
        "limit": 3
      }
    },
    {
      "id": "s2",
      "op": "compare_products",
      "args": {
        "ids": ["$s1.0.id", "$s1.1.id", "$s1.2.id"]
      }
    },
    {
      "id": "s3",
      "op": "get_reviews",
      "args": {
        "product_id": "$s2.mejor_evaluado",
        "limit": 3
      }
    },
    {
      "id": "s4",
      "op": "respond",
      "plantilla": "¡Hola! Para cocinar bastante en casa, te recomiendo especialmente la **{nombre_mejor}** <<rec:{id_mejor}>>, que es la mejor evaluada entre las opciones disponibles. Aquí un resumen de lo que dicen quienes la han usado: {resenas}.\n\nTambién puedes considerar las otras opciones que encontramos: **{nombre_0}** <<rec:{id_0}>> a ${precio_0} CLP y **{nombre_1}** <<rec:{id_1}>> a ${precio_1} CLP. Si quieres comparar las tres: <<cmp:{id_0},{id_1},{id_mejor}>>.\n\nLa más económica del grupo es la de id {mas_barata}, por si el presupuesto es un factor importante.",
      "vars": {
        "nombre_mejor": "$s2.mejor_evaluado",
        "id_mejor": "$s2.mejor_evaluado",
        "resenas": "$s3",
        "nombre_0": "$s1.0.name",
        "id_0": "$s1.0.id",
        "precio_0": "$s1.0.price_clp",
        "nombre_1": "$s1.1.name",
        "id_1": "$s1.1.id",
        "precio_1": "$s1.1.price_clp",
        "mas_barata": "$s2.mas_barato"
      }
    }
  ]
}
